
from sqlalchemy import (
    Column,
    Integer,
    String,
    Numeric,
    Text,
    DateTime,
    JSON,
    func
)
from sqlalchemy.orm import relationship

from app.database.connection import Base


class Order(Base):
    # Database table name
    __tablename__ = "orders"

    # Unique order ID generated by the database
    id = Column(Integer, primary_key=True, index=True)

    # Unique business order number
    order_number = Column(String(50), unique=True, nullable=False, index=True)

    # ID of the customer from the User Service
    # This is not a local user table or foreign key
    user_id = Column(Integer, nullable=False, index=True)

    # Order and payment statuses
    status = Column(String(30), nullable=False, default="PENDING")
    payment_status = Column(String(30), nullable=False, default="PENDING")

    # Financial values use Decimal-compatible Numeric columns
    subtotal = Column(Numeric(12, 2), nullable=False, default=0)
    discount = Column(Numeric(12, 2), nullable=False, default=0)
    tax = Column(Numeric(12, 2), nullable=False, default=0)
    shipping_fee = Column(Numeric(12, 2), nullable=False, default=0)
    total_amount = Column(Numeric(12, 2), nullable=False, default=0)

    # Store the shipping address as a snapshot
    shipping_address = Column(JSON, nullable=False)

    # Optional customer notes
    notes = Column(Text, nullable=True)

    # Timestamps managed by the database
    created_at = Column(DateTime, server_default=func.now(), nullable=False)
    updated_at = Column(
        DateTime,
        server_default=func.now(),
        onupdate=func.now(),
        nullable=False
    )

    # One order can contain many order items
    items = relationship(
        "OrderItem",
        back_populates="order",
        cascade="all, delete-orphan"
    )
